PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,is_admin INTEGER NOT NULL DEFAULT 0 CHECK(is_admin IN (0,1)),created INTEGER NOT NULL);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE instances(id TEXT PRIMARY KEY,name TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES users(id),device TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,device_next TEXT);
CREATE TABLE grants(instance TEXT NOT NULL REFERENCES instances(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('owner','operator','observer')),PRIMARY KEY(instance,user_id));
CREATE TABLE registrations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),claim TEXT NOT NULL,instance_id TEXT NOT NULL);
CREATE TABLE audit(id INTEGER PRIMARY KEY AUTOINCREMENT,at INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,instance TEXT);
CREATE TABLE preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),value TEXT NOT NULL);
CREATE TABLE tickets(token TEXT PRIMARY KEY,session TEXT NOT NULL,instance TEXT NOT NULL,version INTEGER NOT NULL,expires INTEGER NOT NULL);
